import java.util.*;
import java.io.*;

public class Main {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int val) { this.val = val; }
    }

    static List<Integer> levelRange(TreeNode root, int l, int r) {
        // Write your solution here
        // Return the values of levels l..r in level order (they form the linked list).
        return new ArrayList<>();
    }

    static TreeNode buildTree(List<String> tokens) {
        TreeNode root = new TreeNode(Integer.parseInt(tokens.get(0)));
        ArrayDeque<TreeNode> queue = new ArrayDeque<>();
        queue.add(root);
        int i = 1;
        while (!queue.isEmpty() && i < tokens.size()) {
            TreeNode node = queue.poll();
            if (i < tokens.size() && !tokens.get(i).equals("null")) {
                node.left = new TreeNode(Integer.parseInt(tokens.get(i)));
                queue.add(node.left);
            }
            i++;
            if (i < tokens.size() && !tokens.get(i).equals("null")) {
                node.right = new TreeNode(Integer.parseInt(tokens.get(i)));
                queue.add(node.right);
            }
            i++;
        }
        return root;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> tokens = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            StringTokenizer st = new StringTokenizer(line);
            while (st.hasMoreTokens()) tokens.add(st.nextToken());
        }
        int l = Integer.parseInt(tokens.get(0));
        int r = Integer.parseInt(tokens.get(1));
        List<Integer> res = levelRange(buildTree(tokens.subList(2, tokens.size())), l, r);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.size(); i++) sb.append(res.get(i)).append(i + 1 < res.size() ? " " : "");
        System.out.println(sb);
    }
}

